package com.example.discovery.provider.client;import com.example.discovery.provider.config.ProviderProperties;import com.example.discovery.provider.model.RegisterServiceRequest;import jakarta.annotation.PreDestroy;import org.slf4j.*;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.context.event.EventListener;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class RegistryClient{private static final Logger log=LoggerFactory.getLogger(RegistryClient.class);private final RestClient restClient;private final ProviderProperties p;public RegistryClient(RestClient restClient,ProviderProperties p){this.restClient=restClient;this.p=p;} @EventListener(ApplicationReadyEvent.class) public void register(){var req=new RegisterServiceRequest(p.serviceName(),p.instanceId(),p.host(),p.port(),p.healthUrl());restClient.post().uri(p.registryUrl()+"/registry/services").body(req).retrieve().toBodilessEntity();log.info("[PROVIDER] Registered instance: {}",p.instanceId());} @Scheduled(fixedDelayString="${service.discovery.heartbeat-interval:3s}") public void heartbeat(){try{restClient.post().uri(p.registryUrl()+"/registry/services/{s}/{i}/heartbeat",p.serviceName(),p.instanceId()).retrieve().toBodilessEntity();log.info("[PROVIDER] Heartbeat sent: {}",p.instanceId());}catch(Exception ex){log.warn("[PROVIDER] Heartbeat failed for {}: {}",p.instanceId(),ex.getMessage());}} @PreDestroy public void deregister(){try{restClient.delete().uri(p.registryUrl()+"/registry/services/{s}/{i}",p.serviceName(),p.instanceId()).retrieve().toBodilessEntity();log.info("[PROVIDER] Deregistered instance: {}",p.instanceId());}catch(Exception ex){log.warn("[PROVIDER] Deregistration failed for {}",p.instanceId());}}}
